/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    fieldsOf, LAB_COST_MODIFIER_FIELDS, NUMBER_OPTIONS, UNKNOWN_NUMBER_OPTIONS, DECIMAL_OPTIONS, GROUPED_OPTIONS, SECONDS_OPTIONS, DATE_TIME_OPTIONS
 * depends    src/calculators/types, src/formatting/numbers/compute, src/formatting/numbers/types, src/mechanics/effective-paths/common/types
 * used by    src/calculators/registry, src/calculators/specs-formatting
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import type { formatDecimalForDisplay } from '../formatting/numbers/compute'
import type {
  FormatDateTimeForDisplayOptions,
  FormatGroupedNumberOptions,
  FormatNumberForDisplayOptions,
  FormatSecondsAsHoursMinutesOptions,
  FormatUnknownNumberForDisplayOptions,
} from '../formatting/numbers/types'
import type { LabCostModifiers } from '../mechanics/effective-paths/common/types'
import type { CalculatorParamField } from './types'

/**
 * Declare the fields of an options-bag parameter against the type the function takes.
 *
 * The mapped type is the point: it demands exactly the keys of `T`, so adding an
 * option to the interface without declaring it here fails to compile, and so does
 * declaring one the interface does not have. A hand-typed list of names beside a
 * TypeScript interface drifts; the previous `describes` for `formatNumberForDisplay`
 * read "decimals, fallback, notation" and the function takes none of the three.
 */
export function fieldsOf<T extends object>(
  declared: { [K in keyof Required<T>]: Omit<CalculatorParamField, 'name'> },
): readonly CalculatorParamField[] {
  return Object.entries<Omit<CalculatorParamField, 'name'>>(declared)
    .map(([name, field]) => ({ name, ...field }))
}

// ----------------------------------------------------------------- labs ---

/**
 * What `modifiers` may hold, for both lab calculators.
 *
 * One bag feeds two formulas, so a caller can pass the same object to each: the
 * coin cost reads the discount and ignores the speed fields, the duration reads
 * the speed fields and ignores the discount. Each field says which.
 */
export const LAB_COST_MODIFIER_FIELDS = fieldsOf<LabCostModifiers>({
  coinDiscountLabLevel: {
    kind: 'number',
    unit: 'lab level',
    describes: 'level of the Labs Coin Discount lab, 0.3% off per level — the only field lab.coinCost reads',
  },
  labSpeedLabLevel: {
    kind: 'number',
    unit: 'lab level',
    describes: 'level of the Lab Speed lab, 2% faster per level — read by lab.durationDays',
  },
  labSpeedRelicPct: {
    kind: 'number',
    unit: 'fraction',
    describes: 'lab speed from relics, 0.1 for +10% — read by lab.durationDays',
  },
  labSpeedMultiplier: {
    kind: 'number',
    unit: 'multiplier',
    describes: 'the "Speed Up" what-if on top of the two above, 1 when absent — read by lab.durationDays',
  },
})

// ----------------------------------------------------------- formatting ---

type Field = Omit<CalculatorParamField, 'name'>

/** The options `formatNumberForDisplay` reads, shared with the formatter that extends them. */
const NUMBER_OPTION_FIELDS: { [K in keyof Required<FormatNumberForDisplayOptions>]: Field } = {
  mode: { kind: 'string', describes: '"display" (the default), "compact" or "grouped"' },
  smallNumberStrategy: { kind: 'string', describes: '"round" or "preserve" (the default), for a number too small for a unit' },
  smallNumberMaxFractionDigits: { kind: 'number', describes: 'most decimals kept on a number too small for a unit' },
  notationMaxFractionDigits: { kind: 'number', describes: 'most decimals kept on a number written with a unit' },
  useGrouping: { kind: 'boolean', describes: 'thousands separators; on by default in "compact" and "grouped"' },
}

export const NUMBER_OPTIONS = fieldsOf<FormatNumberForDisplayOptions>(NUMBER_OPTION_FIELDS)

export const UNKNOWN_NUMBER_OPTIONS = fieldsOf<FormatUnknownNumberForDisplayOptions>({
  ...NUMBER_OPTION_FIELDS,
  decimalPreference: { kind: 'string', describes: '"Period (.)" (the default) or "Comma (,)"' },
  invalidFallback: { kind: 'string', describes: 'returned for a value that is not a number, "N/A" by default' },
  nullFallback: { kind: 'string', describes: 'returned for null, undefined or an empty string; the invalid fallback by default' },
})

export const DECIMAL_OPTIONS = fieldsOf<NonNullable<Parameters<typeof formatDecimalForDisplay>[1]>>({
  maxDecimals: { kind: 'number', describes: 'most decimals shown' },
  invalidFallback: { kind: 'string', describes: 'returned for anything non-numeric, an empty string by default' },
})

export const GROUPED_OPTIONS = fieldsOf<FormatGroupedNumberOptions>({
  locale: { kind: 'string', describes: 'a BCP 47 locale tag, the runtime default when absent' },
  useGrouping: { kind: 'boolean', describes: 'thousands separators' },
  minimumFractionDigits: { kind: 'number', describes: 'fewest decimals shown' },
  maximumFractionDigits: { kind: 'number', describes: 'most decimals shown' },
  invalidFallback: { kind: 'string', describes: 'returned for anything non-numeric, "0" by default' },
})

export const SECONDS_OPTIONS = fieldsOf<FormatSecondsAsHoursMinutesOptions>({
  zeroFallback: { kind: 'string', describes: 'returned for zero, negative or non-finite input, "0m" by default' },
})

export const DATE_TIME_OPTIONS = fieldsOf<FormatDateTimeForDisplayOptions>({
  invalidFallback: { kind: 'string', describes: 'returned for a value that is not a timestamp, "N/A" by default' },
})
